Based on the commit message, the root cause and the patch provided below, you need to:

1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
net: usb: aqc111: Do not perform PM inside suspend callback

syzbot reports "task hung in rpm_resume"

This is caused by aqc111_suspend calling
the PM variant of its write_cmd routine.

The simplified call trace looks like this:

rpm_suspend()
  usb_suspend_both() - here udev->dev.power.runtime_status == RPM_SUSPENDING
    aqc111_suspend() - called for the usb device interface
      aqc111_write32_cmd()
        usb_autopm_get_interface()
          pm_runtime_resume_and_get()
            rpm_resume() - here we call rpm_resume() on our parent
              rpm_resume() - Here we wait for a status change that will never happen.

At this point we block another task which holds
rtnl_lock and locks up the whole networking stack.

Fix this by replacing the write_cmd calls with their _nopm variants

Reported-by: syzbot+48dc1e8dfc92faf1124c@syzkaller.appspotmail.com
Closes: https://syzkaller.appspot.com/bug?extid=48dc1e8dfc92faf1124c
Fixes: e58ba4544c77 ("net: usb: aqc111: Add support for wake on LAN by MAGIC packet")
Signed-off-by: Nikola Z. Ivanov <zlatistiv@gmail.com>
Link: https://patch.msgid.link/20260313141643.1181386-1-zlatistiv@gmail.com
Signed-off-by: Paolo Abeni <pabeni@redhat.com>

Here is the root cause:
During the USB suspend callback (aqc111_suspend), the driver calls write_cmd functions that internally perform PM runtime operations (usb_autopm_get_interface) which attempt to resume the device. Since the device is already in the RPM_SUSPENDING state, the resume operation waits indefinitely for a status change that never occurs, causing a deadlock. The fix replaces these calls with _nopm variants that do not invoke PM runtime.

Here is the patch:

 static int aqc111_suspend(struct usb_interface *intf, pm_message_t message)
 {
 	struct usbnet *dev = usb_get_intfdata(intf);
 	struct aqc111_data *aqc111_data = dev->driver_priv;
 	u16 temp_rx_ctrl = 0x00;
 	u16 reg16;
 	u8 reg8;

 	usbnet_suspend(intf, message);

 	aqc111_read16_cmd_nopm(dev, AQ_ACCESS_MAC, SFR_RX_CTL, 2, &reg16);
 	temp_rx_ctrl = reg16;
 	/* Stop RX operations*/
 	reg16 &= ~SFR_RX_CTL_START;
 	aqc111_write16_cmd_nopm(dev, AQ_ACCESS_MAC, SFR_RX_CTL, 2, &reg16);
 	/* Force bz */
 	aqc111_read16_cmd_nopm(dev, AQ_ACCESS_MAC, SFR_PHYPWR_RSTCTL,
 			       2, &reg16);
 	reg16 |= SFR_PHYPWR_RSTCTL_BZ;
 	aqc111_write16_cmd_nopm(dev, AQ_ACCESS_MAC, SFR_PHYPWR_RSTCTL,
 				2, &reg16);

 	reg8 = SFR_BULK_OUT_EFF_EN;
 	aqc111_write_cmd_nopm(dev, AQ_ACCESS_MAC, SFR_BULK_OUT_CTRL,
 			      1, 1, &reg8);

 	temp_rx_ctrl &= ~(SFR_RX_CTL_START | SFR_RX_CTL_RF_WAK |
 			  SFR_RX_CTL_AP | SFR_RX_CTL_AM);
 	aqc111_write16_cmd_nopm(dev, AQ_ACCESS_MAC, SFR_RX_CTL,
 				2, &temp_rx_ctrl);

 	reg8 = 0x00;
 	aqc111_write_cmd_nopm(dev, AQ_ACCESS_MAC, SFR_ETH_MAC_PATH,
 			      1, 1, &reg8);

 	if (aqc111_data->wol_flags) {
 		struct aqc111_wol_cfg wol_cfg;

 		memset(&wol_cfg, 0, sizeof(struct aqc111_wol_cfg));

 		aqc111_data->phy_cfg |= AQ_WOL;
 		ether_addr_copy(wol_cfg.hw_addr, dev->net->dev_addr);
 		wol_cfg.flags = aqc111_data->wol_flags;

 		temp_rx_ctrl |= (SFR_RX_CTL_AB | SFR_RX_CTL_START);
 		aqc111_write16_cmd_nopm(dev, AQ_ACCESS_MAC, SFR_RX_CTL,
 					2, &temp_rx_ctrl);
 		reg8 = 0x00;
 		aqc111_write_cmd_nopm(dev, AQ_ACCESS_MAC, SFR_BM_INT_MASK,
 				      1, 1, &reg8);
 		reg8 = SFR_BMRX_DMA_EN;
 		aqc111_write_cmd_nopm(dev, AQ_ACCESS_MAC, SFR_BMRX_DMA_CONTROL,
 				      1, 1, &reg8);
 		reg8 = SFR_RX_PATH_READY;
 		aqc111_write_cmd_nopm(dev, AQ_ACCESS_MAC, SFR_ETH_MAC_PATH,
 				      1, 1, &reg8);
 		reg8 = 0x07;
 		aqc111_write_cmd_nopm(dev, AQ_ACCESS_MAC, SFR_RX_BULKIN_QCTRL,
 				      1, 1, &reg8);
 		reg8 = 0x00;
 		aqc111_write_cmd_nopm(dev, AQ_ACCESS_MAC,
 				      SFR_RX_BULKIN_QTIMR_LOW, 1, 1, &reg8);
 		aqc111_write_cmd_nopm(dev, AQ_ACCESS_MAC,
 				      SFR_RX_BULKIN_QTIMR_HIGH, 1, 1, &reg8);
 		reg8 = 0xFF;
 		aqc111_write_cmd_nopm(dev, AQ_ACCESS_MAC, SFR_RX_BULKIN_QSIZE,
 				      1, 1, &reg8);
 		aqc111_write_cmd_nopm(dev, AQ_ACCESS_MAC, SFR_RX_BULKIN_QIFG,
 				      1, 1, &reg8);

 		aqc111_read16_cmd_nopm(dev, AQ_ACCESS_MAC,
 				       SFR_MEDIUM_STATUS_MODE, 2, &reg16);
 		reg16 |= SFR_MEDIUM_RECEIVE_EN;
 		aqc111_write16_cmd_nopm(dev, AQ_ACCESS_MAC,
 					SFR_MEDIUM_STATUS_MODE, 2, &reg16);

-		aqc111_write_cmd(dev, AQ_WOL_CFG, 0, 0,
-				 WOL_CFG_SIZE, &wol_cfg);
-		aqc111_write32_cmd(dev, AQ_PHY_OPS, 0, 0,
-				   &aqc111_data->phy_cfg);
+		aqc111_write_cmd_nopm(dev, AQ_WOL_CFG, 0, 0,
+				      WOL_CFG_SIZE, &wol_cfg);
+		aqc111_write32_cmd_nopm(dev, AQ_PHY_OPS, 0, 0,
+					&aqc111_data->phy_cfg);
 	} else {
 		aqc111_data->phy_cfg |= AQ_LOW_POWER;
-		aqc111_write32_cmd(dev, AQ_PHY_OPS, 0, 0,
-				   &aqc111_data->phy_cfg);
+		aqc111_write32_cmd_nopm(dev, AQ_PHY_OPS, 0, 0,
+					&aqc111_data->phy_cfg);

 		/* Disable RX path */
 		aqc111_read16_cmd_nopm(dev, AQ_ACCESS_MAC,
 				       SFR_MEDIUM_STATUS_MODE, 2, &reg16);
 		reg16 &= ~SFR_MEDIUM_RECEIVE_EN;
 		aqc111_write16_cmd_nopm(dev, AQ_ACCESS_MAC,
 					SFR_MEDIUM_STATUS_MODE, 2, &reg16);
 	}

 	return 0;
 }



